#include <stdio.h>
#include <stdlib.h>

long long numSubarrayProductLessThanK(int *nums, int numsSize, int k) {
    if (k <= 1) return 0;
    long long product = 1;
    long long answer = 0;
    int left = 0;
    for (int right = 0; right < numsSize; ++right) {
        product *= nums[right];
        while (product >= k) {
            product /= nums[left++];
        }
        answer += (long long)right - left + 1;
    }
    return answer;
}

